/* ===== Config: paste your deployed Apps Script Web App URL here (site owner only – users never see this) ===== */
const API_URL = 'https://script.google.com/macros/s/AKfycbyFB84vtRsKOjwm6AOUJK3hHpffnBINoBN9u5RVmchHVdz5Clpfd7_40st-B9s8Jp7aIw/exec';
const $ = (s, r = document) => r.querySelector(s), $$ = (s, r = document) => [...r.querySelectorAll(s)];
const z = x => +x || 0;
const inr = n => isFinite(n) ? '₹' + Math.round(n).toLocaleString('en-IN') : '–';
const inr2 = n => isFinite(n) ? '₹' + n.toLocaleString('en-IN', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : '–';
const num = n => isFinite(n) ? (+(+n).toFixed(2)).toLocaleString('en-IN') : '–';
const api = () => API_URL;
const LOGO = 'data:image/png;base64,';   // embedded logo for the PDF and Excel downloads

/* ===== Powder / material list – prices, density & wastage from F-APPLN-01 R9 (CE_R1: C8, C9, C13) ===== */
// HT hours (stress relieving) keep the values of the previous STLR 220 sheet (5.5 hrs heat treatment, 3.5 hrs furnace power); editable.
const MAT0 = [['SS304', 3200, 8, .3], ['AlSi10Mg', 4500, 2.7, .3], ['CuCrZr', 12000, 8.9, 0], ['SS316L', 2400, 8, .3], ['18Ni300', 5200, 8.1, .5], ['H13', 4500, 8.1, .5],
  ['StrengthAl', 15000, 2.5, 0], ['17-4PH', 2600, 7.8, .5], ['IN718', 8000, 8.1, .5], ['IN625', 8000, 8.1, .5], ['Ti6Al4V', 18500, 4.4, .6], ['CoCr', 8500, 10, .3]]
  .map(([n, p, dens, waste]) => ({ n, p, dens, waste, ht: 5.5, fp: 3.5 }));
/* ===== Machine list – STLR 220 keeps its finance block; the machines of the new sheet use the fixed rate per hr (note D19) ===== */
const MCH0 = [
  { n: 'STLR 220', laser: 'Single laser', price: 12850000, rate: 10.5, yrs: 5, util: 80, fixed: null },
  { n: 'STLR180', laser: '', price: null, rate: null, yrs: null, util: null, fixed: 1500 },
  { n: 'STLR400-1', laser: 'Dual laser', price: null, rate: null, yrs: null, util: null, fixed: 3000 },
  { n: 'STLR400-2', laser: 'Dual laser', price: null, rate: null, yrs: null, util: null, fixed: 3500 },
  { n: 'SLM', laser: '', price: null, rate: null, yrs: null, util: null, fixed: 3000 }];
let POW = JSON.parse(JSON.stringify(MAT0)), MCH = JSON.parse(JSON.stringify(MCH0));

/* ===== State. Blank on open / New quote; machine & material selection fills the rest ===== */
const SHARED = { i: { prep: 3, wire: 10, supHrs: 160, supRate: 100, filter: 150, recoater: 525, kw: 4, pRate: 8, gasF: 1, gRate: 8, opF: 0.5, opRate: 150, margin: 15, adv: 50, pf: 750 },
  furn: { price: 1000000, rate: 10.5, yrs: 5, util: 90, kwh: 25, kwhRate: 8, other: 30 }, wire: { price: 1300000, rate: 10.5, yrs: 5, util: 85, cons: 100, op: 150, pwr: 8 } };
const nul = o => Object.fromEntries(Object.keys(o).map(k => [k, null]));
const BLANK = () => ({ i: { machine: '', material: '', customer: '', part: '', laser: '', parts: null, layer: null, days: null, hrs: null, kg: null, sets: null, units: null,
    pv: null, sv: null, htHrs: null, fpHrs: null, price: null, ...nul(SHARED.i), roundTo: 1000 },
  m: { stlr: { price: null, rate: null, yrs: null, util: null, fixed: null }, furn: nul(SHARED.furn), wire: nul(SHARED.wire) }, days: 25 });
let S = BLANK(), curId = '';

/* ===== Maths (same formulas as the Excel) ===== */
const emi = (P, r, y) => { if (!P || !y) return 0; const i = r / 1200, n = y * 12; return i ? P * i * (1 + i) ** n / ((1 + i) ** n - 1) : P / n; };
const r100 = x => Math.round(x / 100) * 100;            // EMIs in the sheet are rounded to the nearest 100
const hrsM = u => S.days * 24 * u / 100 || Infinity;    // =25*24*utilisation
const matOf = () => POW.find(p => p.n === S.i.material);
function calc() {
  const i = {}, m = { stlr: {}, furn: {}, wire: {} }, o = {};
  for (const k in S.i) i[k] = z(S.i[k]); for (const g in m) for (const k in S.m[g]) m[g][k] = z(S.m[g][k]);
  const started = !!(S.i.machine || S.i.material);                                                // blank page = all zeros
  i.sets = i.sets || 1; i.units = i.units || (started ? 1 : 0); i.roundTo = i.roundTo || 1000;          // blank units count as 1 only once a machine / material is selected
  o.printHrs = i.days * 24 + i.hrs;                                                                     // C8
  o.emiS = r100(emi(m.stlr.price, m.stlr.rate, m.stlr.yrs));                                            // C35
  o.mhrS = m.stlr.fixed > 0 ? m.stlr.fixed : o.emiS / hrsM(m.stlr.util);                               // C37 (fixed rate per hr overrides EMI)
  o.emiF = r100(emi(m.furn.price, m.furn.rate, m.furn.yrs)); o.mhrF = o.emiF / hrsM(m.furn.util);     // C41 C43
  o.pwrF = m.furn.kwh * m.furn.kwhRate + m.furn.other;                                                  // C49
  o.emiW = r100(emi(m.wire.price, m.wire.rate, m.wire.yrs)); o.mhrW = o.emiW / hrsM(m.wire.util);     // C53 C56
  o.wireMHR = Math.ceil((m.wire.cons + o.mhrW + m.wire.op + m.wire.pwr) / 10) * 10;                    // C59
  const u = i.units, h = o.printHrs, q1 = h, q2 = i.prep;
  o.rows = [[q1, o.mhrS], [q2, o.mhrS], [i.kg * u, i.price], [h * u, i.filter], [u, i.recoater], [i.wire, o.wireMHR], [i.supHrs, i.supRate], [i.kw * h * u, i.pRate],
    [i.gasF * h * u, i.gRate], [i.htHrs, o.mhrF], [i.fpHrs, o.pwrF], [(q1 + q2) * i.opF, i.opRate]].map(([q, r]) => ({ q, r, t: q * r }));
  o.total = o.rows.reduce((a, r) => a + r.t, 0);                                                        // E26
  o.perSet = o.total / i.sets; o.margin = o.total * i.margin / 100;                                     // E27 E28
  o.round = Math.ceil(+((o.total + o.margin) / i.roundTo).toPrecision(15)) * i.roundTo;                 // E29
  o.adv = o.round * i.adv / 100; o.advPF = o.adv + i.pf; o.perPart = o.round / i.parts;                 // G29 J29 E30
  const M = matOf(); o.estKg = M ? (i.pv + i.sv + z(M.waste) * (i.pv + i.sv)) / 1000 * z(M.dens) : 0;   // optional kg estimator (CE_R1 C14)
  return o;
}

/* ===== Cost table ===== */
const ROWS = [
  ['machine cost (hrs)', 0, 0], ['Preparation time & cooling time (hrs)', 'prep', 0], ['Powder cost (kg)', 0, 'price'], ['Filter cost (hrs)', 0, 'filter'], ['Recoater cost (hrs)', 0, 'recoater'],
  ['Wire cut cost (hrs)', 'wire', 0], ['Support removal cost (hrs)', 'supHrs', 'supRate', 1], ['Power cost (hrs)', 0, 'pRate'], ['Gas - air cost (hrs)', 0, 'gRate'],
  ['Heat treatment cost - Stress relieving (hrs)', 'htHrs', 0, 1], ['Power cost for furnace (hrs)', 'fpHrs', 0, 1], ['Machine operator cost (hrs)', 0, 'opRate']];
const rowLabel = n => n === 0 ? `${S.i.machine || 'Machine'} machine cost (hrs)` : ROWS[n][0];
const inp = (k, w) => `<input type="number" step="any" data-k="${k}" ${w ? 'class="y"' : ''}>`;
function buildTable() {
  $('#costTbl tbody').innerHTML = ROWS.map(([l, qk, rk, y], n) => `<tr class="${y ? 'yel' : ''}"><td>${n + 1}</td><td data-lab="${n}">${l}</td>
    <td>${qk ? inp(qk, 1) : `<span data-q="${n}"></span>`}</td><td>${rk ? inp(rk, rk === 'price' || rk === 'supRate') : `<span data-r="${n}"></span>`}</td>
    <td data-t="${n}"></td><td data-p="${n}"></td></tr>`).join('');
  $('#foot').innerHTML = `<tr><td></td><td></td><td></td><td>Total cost</td><td data-o="total"></td><td data-o="pTotal"></td></tr>
   <tr><td></td><td></td><td></td><td>Per set cost (Rs)</td><td data-o="perSet"></td><td></td></tr>
   <tr><td></td><td></td><td></td><td>Margin ${inp('margin')} %</td><td data-o="margin"></td><td data-o="pMargin"></td></tr>
   <tr class="hi"><td></td><td></td><td></td><td>Total round-off</td><td data-o="round"></td><td>100%</td></tr>
   <tr class="hi"><td></td><td></td><td></td><td>Per part cost</td><td data-o="perPart"></td><td></td></tr>`;
}
function buildMachines() {
  const f = (g, k, l, u) => `<label>${l}<span class="u"><input type="number" step="any" data-m="${g}.${k}"><i>${u}</i></span></label>`;
  const base = g => f(g, 'price', 'Machine price', 'INR') + f(g, 'rate', 'Interest rate', '% p.a') + f(g, 'yrs', 'No. of years', 'yrs') + f(g, 'util', 'Utilisation (25 days/month)', '%');
  $('#machines').innerHTML = `
  <div class="mc"><h3><span data-lab2>Selected machine</span></h3>${base('stlr')}${f('stlr', 'fixed', 'Fixed rate per hr (blank = use EMI)', 'INR/hr')}
   <div class="o"><span>Monthly EMI</span><span data-o="emiS"></span></div><div class="o"><span>Machine hour rate (MHR) used</span><span data-o="mhrS"></span></div></div>
  <div class="mc"><h3>HT furnace</h3>${base('furn')}${f('furn', 'kwh', 'Total rating of furnace', 'kWh')}${f('furn', 'kwhRate', 'Per unit cost of kWh', 'INR')}${f('furn', 'other', 'Other costs', 'INR')}
   <div class="o"><span>Monthly EMI</span><span data-o="emiF"></span></div><div class="o"><span>MHR</span><span data-o="mhrF"></span></div><div class="o"><span>Total power cost / hr</span><span data-o="pwrF"></span></div></div>
  <div class="mc"><h3>Wire cut</h3>${base('wire')}${f('wire', 'cons', 'Consumable costs', 'INR')}${f('wire', 'op', 'Operator cost per hr', 'INR')}${f('wire', 'pwr', 'Power cost per hr', 'INR')}
   <div class="o"><span>Monthly EMI</span><span data-o="emiW"></span></div><div class="o"><span>MHR</span><span data-o="mhrW"></span></div><div class="o"><span>Total MHR (rounded up to 10)</span><span data-o="wireMHR"></span></div></div>`;
  const A = [['kw', 'Machine power for power cost', 'kW', 'C21'], ['gasF', 'Gas-air factor (× print hrs)', 'factor', 'C22'], ['opF', 'Operator hrs factor (× machine + prep hrs)', 'factor', 'C25'],
    ['roundTo', 'Round-up total to nearest', 'Rs', 'E29'], ['adv', 'Advance', '%', 'G29'], ['pf', 'P&F charges (added to advance)', 'Rs', 'J29']];
  $('#aTbl tbody').innerHTML = A.map(([k, l, u, c]) => `<tr><td class="l">${l}</td><td><input type="number" step="any" data-k="${k}"></td><td class="l">${u}</td></tr>`).join('');
}

/* ===== Render / binding ===== */
const opts = (a, ph) => `<option value="">${ph}</option>` + a.map(x => `<option>${x}</option>`).join('');
function fillSelects() {
  $('#machine').innerHTML = opts(MCH.map(x => x.n), 'Select machine'); $('#material').innerHTML = opts(POW.map(x => x.n), 'Select material');
  if (S.i.machine && !MCH.some(x => x.n === S.i.machine)) $('#machine').insertAdjacentHTML('beforeend', `<option>${S.i.machine}</option>`);
  if (S.i.material && !POW.some(x => x.n === S.i.material)) $('#material').insertAdjacentHTML('beforeend', `<option>${S.i.material}</option>`);
  bind();
}
function bind() {
  $$('[data-k]').forEach(e => { if (e.tagName === 'SELECT' || document.activeElement !== e) { const v = S.i[e.dataset.k]; e.value = v == null ? '' : v; } });
  $$('[data-m]').forEach(e => { if (document.activeElement !== e) { const [g, k] = e.dataset.m.split('.'), v = S.m[g][k]; e.value = v == null ? '' : v; } });
}
function render() {
  const o = calc(), set = (s, t) => $$(s).forEach(e => e.textContent = t), pc = t => o.round ? Math.round(t / o.round * 100) + '%' : '0%';
  o.rows.forEach((r, n) => { set(`[data-lab="${n}"]`, rowLabel(n)); set(`[data-q="${n}"]`, num(r.q)); set(`[data-r="${n}"]`, num(r.r)); set(`[data-t="${n}"]`, inr(r.t)); set(`[data-p="${n}"]`, pc(r.t)); });
  const fm = { printHrs: num, estKg: n => num(n) + ' kg', emiS: inr, emiF: inr, emiW: inr, mhrS: inr2, mhrF: inr2, mhrW: inr2, wireMHR: inr, pwrF: inr, total: inr, perSet: inr, margin: inr, round: inr, adv: inr, advPF: inr, perPart: inr2 };
  Object.keys(fm).forEach(k => set(`[data-o="${k}"]`, fm[k](o[k])));
  set('[data-o="pTotal"]', pc(o.total)); set('[data-o="pMargin"]', pc(o.margin));
  set('[data-lab2]', (S.i.machine || 'Selected machine') + ' – machine hour rate'); $('#lTarget').options[0].textContent = S.i.machine ? S.i.machine + ' (selected machine)' : 'Selected machine';
  return o;
}
function applyMaterial() {   // material dropdown -> powder price/kg, HT hrs, furnace power hrs
  const p = matOf(); Object.assign(S.i, p ? { price: p.p, htHrs: p.ht, fpHrs: p.fp } : { price: null, htHrs: null, fpHrs: null }); bind();
}
function applyMachine() {    // machine dropdown -> laser, machine rate / finance block and the shared rates
  const mc = MCH.find(x => x.n === S.i.machine);
  if (!mc) { Object.assign(S.i, { laser: '', ...nul(SHARED.i) }); S.m = BLANK().m; }
  else { Object.assign(S.i, { laser: mc.laser, ...SHARED.i }); S.m = { stlr: { price: mc.price, rate: mc.rate, yrs: mc.yrs, util: mc.util, fixed: mc.fixed }, furn: { ...SHARED.furn }, wire: { ...SHARED.wire } }; }
  bind();
}
document.addEventListener('input', e => {
  const t = e.target;
  if (t.dataset.k) { S.i[t.dataset.k] = t.type === 'number' ? (t.value === '' ? null : parseFloat(t.value)) : t.value; if (t.dataset.k === 'material') applyMaterial(); if (t.dataset.k === 'machine') applyMachine(); render(); }
  else if (t.dataset.m) { const [g, k] = t.dataset.m.split('.'); S.m[g][k] = t.value === '' ? null : parseFloat(t.value); render(); }
});
$('#bUse').onclick = () => { const o = calc(); if (!o.estKg) return toast('Select a material and enter the volumes first'); S.i.kg = +o.estKg.toFixed(2); bind(); render(); };
$$('.tabs button').forEach(b => b.onclick = () => { $$('.tabs button,.tab').forEach(x => x.classList.remove('on')); b.classList.add('on'); $('#' + b.dataset.t).classList.add('on'); });

/* ===== Lists (powder & machine), editable and stored in the sheet ===== */
function listsUI() {
  $('#pTbl').innerHTML = '<thead><tr><th>Powder</th><th>Price / kg</th><th>Density g/cc</th><th>Wastage</th><th>HT time (hrs)</th><th>HT power (hrs)</th><th></th></tr></thead><tbody>' +
    POW.map((p, n) => `<tr><td><input data-p="${n}.n" value="${p.n}"></td>` + ['p', 'dens', 'waste', 'ht', 'fp'].map(k => `<td><input type="number" step="any" data-p="${n}.${k}" value="${p[k]}"></td>`).join('') + `<td><button class="ghost" data-del="${n}">Remove</button></td></tr>`).join('') + '</tbody>';
  const nv = v => v == null ? '' : v;
  $('#kTbl').innerHTML = '<thead><tr><th>Machine</th><th>Lasers</th><th>Price</th><th>Interest %</th><th>Years</th><th>Util %</th><th>Fixed rate / hr</th><th></th></tr></thead><tbody>' +
    MCH.map((m, n) => `<tr><td><input data-kn="${n}.n" value="${m.n}"></td><td><select data-kn="${n}.laser">${['', 'Single laser', 'Dual laser', 'Quad laser'].map(x => `<option${x === m.laser ? ' selected' : ''}>${x}</option>`).join('')}</select></td>` +
      ['price', 'rate', 'yrs', 'util', 'fixed'].map(k => `<td><input type="number" step="any" data-kn="${n}.${k}" value="${nv(m[k])}"></td>`).join('') + `<td><button class="ghost" data-kd="${n}">Remove</button></td></tr>`).join('') + '</tbody>';
}
document.addEventListener('change', e => {
  const t = e.target;
  if (t.dataset.p) { const [n, k] = t.dataset.p.split('.'); POW[n][k] = k === 'n' ? t.value : z(t.value); fillSelects(); render(); autoSave(); }
  if (t.dataset.kn) { const [n, k] = t.dataset.kn.split('.'); MCH[n][k] = k === 'n' || k === 'laser' ? t.value : (t.value === '' ? null : +t.value); fillSelects(); autoSave(); }
});
document.addEventListener('click', e => {
  const d = e.target.dataset; if (d.del != null) { POW.splice(+d.del, 1); listsUI(); fillSelects(); render(); autoSave(); } if (d.kd != null) { MCH.splice(+d.kd, 1); listsUI(); fillSelects(); autoSave(); }
});
$('#pAdd').onclick = () => { POW.push({ n: 'New powder', p: 0, dens: 0, waste: 0, ht: 5.5, fp: 3.5 }); listsUI(); fillSelects(); autoSave(); };
$('#kAdd').onclick = () => { MCH.push({ n: 'New machine', laser: '', price: null, rate: null, yrs: null, util: null, fixed: null }); listsUI(); fillSelects(); autoSave(); };
let st; const autoSave = () => { clearTimeout(st); st = setTimeout(saveLists, 700); };   // every add / edit / remove is stored automatically
async function saveLists() {
  try {
    const r = await call('saveMasters', { materials: POW, machines: MCH });
    if (!r.ok) throw new Error(r.error || 'request rejected');
    toast(api() ? `Saved to Google Sheet – ${r.powders ?? POW.length} powders, ${r.machines ?? MCH.length} machines` : 'Saved in this browser only – set API_URL in script.js to store in the Google Sheet');
  } catch (e) { toast('Could not save to Google Sheet: ' + e.message + '. Redeploy Code.gs as a NEW version with access "Anyone".'); }
}
$$('#pSave,#kSave').forEach(b => b.onclick = saveLists);

/* ===== Loan calculator ===== */
const L = { amt: 15800000, rate: 10.5, yrs: 5 };
function loan(from) {
  const ids = { amt: 'Amt', rate: 'Rate', yrs: 'Yrs' };
  if (from) L[from] = parseFloat($('#l' + ids[from]).value) || 0;
  for (const k in ids) { if (document.activeElement.id !== 'l' + ids[k]) $('#l' + ids[k]).value = L[k]; $('#s' + ids[k]).value = L[k]; }
  const e = emi(L.amt, L.rate, L.yrs), tot = e * L.yrs * 12, int = tot - L.amt, c = 2 * Math.PI * 45;
  $('#rEmi').textContent = inr(e); $('#rPr').textContent = inr(L.amt); $('#rInt').textContent = inr(int); $('#rTot').textContent = inr(tot);
  $('#arc').setAttribute('stroke-dasharray', `${c * (tot ? int / tot : 0)} ${c}`);
}
['Amt', 'Rate', 'Yrs'].forEach(n => { const k = n.toLowerCase(); $('#l' + n).oninput = () => loan(k); $('#s' + n).oninput = e => { L[k] = +e.target.value; loan(); }; });
$('#lApply').onclick = () => { const g = $('#lTarget').value; if (g === 'stlr' && !S.i.machine) return toast('Select a machine in Project details first'); Object.assign(S.m[g], { price: L.amt, rate: L.rate, yrs: L.yrs }); if (g === 'stlr') S.m.stlr.fixed = null; bind(); render(); toast('Applied – EMI & machine hour rate updated'); };

// ===== Excel formula map (tab commented out in index.html – remove the "// " in front of each line below to show it again) =====
// const FM = `C8|Total print time (hrs)|=(2*24)+1|days × 24 + hours (inputs C6–C9 yellow)
// C14|Machine hours|=C8|C8
// D14|Machine hour rate|=C37|C35 EMI ÷ C36 hours – or the fixed rate per hr of the machine (STLR180 1500 · STLR400-1 & SLM 3000 · STLR400-2 3500)
// E14|Machine cost|=C14*D14|C14, D14
// C16|Powder qty (kg)|=C9*C11|Kg per build × No. of units (C11)
// E16|Powder cost|=D16*C16|D16 price/kg (yellow, filled from the material dropdown – CE_R1 C8)
// C17|Filter hrs|=C8*C11|Print time × units; rate D17
// C18|Recoater qty|=C11|Units; rate D18
// C19|Wire cut hrs|10|manual; D19 = C59 (Total MHR)
// E20|Support removal|=D20*C20|C20 hrs (yellow) × D20 rate (yellow)
// C21|Power qty|=4*C8*C11|4 kW × print hrs × units; rate D21
// C22|Gas-air qty|=1*C8*C11|print hrs × units; rate D22
// D23|HT MHR|=C43|C41 ÷ C42; C23 hrs (yellow)
// D24|Furnace power / hr|=C49|C47 (C45×C46) + C48; C24 hrs (yellow)
// C25|Operator hrs|=(C14+C15)*0.5|machine + prep hrs × 50%; rate D25
// E26|Total cost|=SUM(E14:E25)|all item totals
// E27|Per set cost|=E26/C10|C10 No. of sets
// E28|Margin|=E26*15%|E26
// E29|Total round-off|=ROUNDUP((E26+E28)/1000,0)*1000|E26, E28
// G29|Advance (50%)|=E29/2|E29
// J29|Advance with P&F|=G29+750|G29
// E30|Per part cost|=E29/C6|C6 total parts / sets per build
// Estimator|Material kg from volume|=(part+support+wastage×(part+support))/1000×density|CE_R1 C14; density = C9, wastage = C13 of the powder list`.split('\n').map(l => l.split('|'));
