/* ===== Backend (Google Apps Script + Google Sheet) with browser fallback ===== */
async function call(action, data = {}) {
  const url = api();
  if (!url) {
    const q = JSON.parse(localStorage.getItem('quotes') || '[]');
    if (action === 'save') { const k = q.findIndex(x => x.id === data.id); k < 0 ? q.unshift(data) : q[k] = data; localStorage.setItem('quotes', JSON.stringify(q)); return { ok: true }; }
    if (action === 'delete') { localStorage.setItem('quotes', JSON.stringify(q.filter(x => x.id !== data.id))); return { ok: true }; }
    if (action === 'list') return { ok: true, quotes: q };
    if (action === 'masters') return { ok: true, ...JSON.parse(localStorage.getItem('masters') || '{}') };
    if (action === 'saveMasters') { localStorage.setItem('masters', JSON.stringify(data)); return { ok: true }; }
  }
  const res = action === 'list' || action === 'masters' ? await fetch(`${url}?action=${action}`) : await fetch(url, { method: 'POST', body: JSON.stringify({ action, ...data }) });
  const txt = await res.text();
  try { return JSON.parse(txt); } catch (e) { throw new Error('the Google Sheet script did not return data (web app access must be "Anyone")'); }
}
async function refreshList() {
  try {
    const r = await call('list'); window._q = r.quotes || [];
    $('#qTbl tbody').innerHTML = window._q.map(q => `<tr><td class="l">${new Date(q.saved).toLocaleString('en-IN')}</td><td class="l">${q.state.i.customer || '–'}</td><td class="l">${q.state.i.part || '–'}</td>
      <td class="l">${q.state.i.machine || '–'} / ${q.state.i.material || '–'}</td><td>${inr2(q.perPart)}</td><td><button class="ghost" data-load="${q.id}">Open</button> <button class="ghost" data-rm="${q.id}">Delete</button></td></tr>`).join('') || '<tr><td colspan="6" class="l">No saved quotes yet.</td></tr>';
  } catch (e) { toast('Could not load saved quotes'); }
}
document.addEventListener('click', async e => {
  if (e.target.dataset.load) { const q = window._q.find(x => x.id === e.target.dataset.load); S = q.state; curId = q.id; fillSelects(); render(); scrollTo(0, 0); toast('Quote loaded'); }
  if (e.target.dataset.rm && confirm('Delete this quote?')) { await call('delete', { id: e.target.dataset.rm }); refreshList(); }
});
$('#bSave').onclick = async () => {
  const o = calc(); curId = curId || 'Q' + Date.now();
  const r = await call('save', { id: curId, saved: new Date().toISOString(), perPart: o.perPart, total: o.total, round: o.round, state: S });
  toast(r.ok ? 'Quote saved' : 'Save failed: ' + r.error); refreshList();
};
$('#bNew').onclick = () => { S = BLANK(); curId = ''; fillSelects(); render(); scrollTo(0, 0); };
let tm; function toast(t) { const el = $('#toast'); el.textContent = t; el.classList.add('on'); clearTimeout(tm); tm = setTimeout(() => el.classList.remove('on'), Math.max(2600, t.length * 70)); }

async function init() {
  try {
    const r = await call('masters'), hp = r.materials && r.materials.length, hm = r.machines && r.machines.length;
    if (hp) POW = r.materials; if (hm) MCH = r.machines;
    if (api() && (!hp || !hm)) saveLists();   // empty Powders / Machines tab -> fill the sheet with the current lists
  } catch (e) { toast('Could not load the saved lists – using defaults. ' + e.message); }
  buildTable(); buildMachines(); listsUI(); fillSelects(); render(); loan(); refreshList();
}
